[
  {
    "text": "The claim that innovative design strategies eliminate at-resolution stitching for all logic and DRAM applications is not uniformly demonstrated; published evidence is largely limited to DRAM storage node contacts using central obscuration illumination at specific pitches.",
    "topic": "Scope of demonstrated stitching-free solutions"
  },
  {
    "text": "For logic applications, stitching-free high-NA EUV at minimal pitches typically requires layout restrictions or mask engineering that are not yet verified across diverse standard cell libraries, unlike DRAM where repetitive array patterns simplify the problem.",
    "topic": "Logic vs. DRAM design constraints"
  },
  {
    "text": "Simulations show sufficient process window for single-exposure stitching-free DRAM contacts at sub-30 nm pitch with annular illumination, but experimental validation of across-field overlay, OPC fidelity, and defect density is incomplete.",
    "topic": "Experimental validation gap"
  },
  {
    "text": "Stitching elimination for large logic die (>26 mm) using high-NA EUV remains unproven because full-field single-exposure is restricted to die sizes within the scanner’s half-field imaging capability, unless multi-reticle stitching is employed at lower resolution.",
    "topic": "Field-size limitation for logic"
  }
]
